package main

const perimeterAdminPage = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Canicule</title><style>*{box-sizing:border-box}body{margin:0;background:#eef3f1;color:#17201f;font:16px system-ui,sans-serif}header{background:#173d38;color:#fff;padding:26px max(5vw,24px)}main{max-width:1100px;margin:30px auto;padding:0 20px}.card{background:#fff;border-radius:10px;padding:26px;margin-bottom:20px}label{display:block;font-weight:650;margin:12px 0 5px}input,select{width:100%;padding:10px;border:1px solid #aec4be;border-radius:5px;font:inherit}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.perimeter{border-top:1px solid #d9e5e2;margin-top:20px;padding-top:12px}.notice{padding:12px;border-radius:6px;margin-bottom:18px}.ok{background:#dcf4e8}.error{background:#fbe2e1;color:#8b2420}button{background:#dc5b2f;border:0;border-radius:5px;color:#fff;padding:11px 18px;font-weight:700;cursor:pointer}.secondary{background:#315d56}.remove{background:#8b2420;float:right}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><header><h1>Canicule</h1><p>Administration de la surveillance vigilance Meteo France</p></header><main><p><a href="/">Carte</a> | <a href="/templates">Modeles d'e-mails</a></p>{{if .Message}}<div class="notice ok">{{.Message}}</div>{{end}}{{if .Error}}<div class="notice error">{{.Error}}</div>{{end}}<form method="post"><section class="card"><h2>Reglages SMTP</h2><div class="grid"><label>Hote SMTP<input name="smtp_host" value="{{.Config.SMTP.Host}}"></label><label>Port<input name="smtp_port" value="{{.Config.SMTP.Port}}"></label><label>Expediteur<input name="smtp_sender" value="{{.Config.SMTP.Sender}}"></label><label>Nom expediteur<input name="smtp_sender_name" value="{{.Config.SMTP.SenderName}}"></label></div><label><input type="checkbox" name="smtp_tls" {{if .Config.SMTP.UseTLS}}checked{{end}}> STARTTLS</label><label><input type="checkbox" name="smtp_ssl" {{if .Config.SMTP.UseSSL}}checked{{end}}> SSL</label><label><input type="checkbox" name="smtp_dry_run" {{if .Config.SMTP.DryRun}}checked{{end}}> Simulation</label></section><section class="card"><h2>Surveillance</h2><div class="grid"><label>Seuil global<select name="min_alert_color">{{range $c:=colors}}<option value="{{$c}}" {{if eq $c $.Config.GlobalSettings.MinAlertColor}}selected{{end}}>{{$c}}</option>{{end}}</select></label><label>Fichier d'etat<input name="state_file" value="{{.Config.GlobalSettings.StateFilePath}}"></label><label>Dossier des modeles<input name="template_dir" value="{{.Config.GlobalSettings.TemplateDir}}"></label><label>Sujet<input name="subject_template" value="{{.Config.GlobalSettings.SubjectTemplate}}"></label></div><label><input type="checkbox" name="only_notify" {{if .Config.GlobalSettings.OnlyNotifyOnChange}}checked{{end}}> Notifier uniquement lors d'un changement</label></section><section class="card"><h2>Perimetres surveilles</h2><p>Codes departementaux separes par des virgules. Une alerte est envoyee par departement concerne.</p><input type="hidden" id="region_count" name="region_count" value="{{len .Config.Regions}}"><div id="regions">{{range $i,$r:=.Config.Regions}}<section class="perimeter"><button type="button" class="remove" onclick="this.parentElement.remove();renumber()">Retirer</button><div class="grid"><label>Nom<input data-field="name" name="region_{{$i}}_name" value="{{$r.Name}}"></label><label>Seuil<select data-field="color" name="region_{{$i}}_color"><option value="">Reglage global</option>{{range $c:=colors}}<option value="{{$c}}" {{if eq $c $r.MinAlertColor}}selected{{end}}>{{$c}}</option>{{end}}</select></label></div><label>Departements<input data-field="departments" name="region_{{$i}}_departments" value="{{join $r.DepartmentCodes ", "}}"></label><label>Destinataires<input data-field="recipients" name="region_{{$i}}_recipients" value="{{join $r.DistList ", "}}"></label></section>{{end}}</div><button type="button" class="secondary" onclick="addPerimeter()">Ajouter un perimetre</button> <button>Enregistrer la configuration</button></section></form><template id="perimeter-template"><section class="perimeter"><button type="button" class="remove" onclick="this.parentElement.remove();renumber()">Retirer</button><div class="grid"><label>Nom<input data-field="name"></label><label>Seuil<select data-field="color"><option value="">Reglage global</option>{{range $c:=colors}}<option value="{{$c}}">{{$c}}</option>{{end}}</select></label></div><label>Departements<input data-field="departments" placeholder="ex. 75, 77"></label><label>Destinataires<input data-field="recipients"></label></section></template><script>function renumber(){let a=document.querySelectorAll('#regions .perimeter');a.forEach((s,i)=>s.querySelectorAll('[data-field]').forEach(f=>f.name='region_'+i+'_'+f.dataset.field));document.getElementById('region_count').value=a.length}function addPerimeter(){let s=document.getElementById('perimeter-template').content.firstElementChild.cloneNode(true);document.getElementById('regions').appendChild(s);renumber()}</script></main></body></html>`
